create or replace function private.user_has_adult_work_attestation(p_user_id uuid) returns boolean language sql stable security definer set search_path to '' as $function$ select exists(select 1 from public.user_policy_acknowledgements a where a.user_id=p_user_id and a.policy_key='adult_work_eligibility' and a.accepted=true and a.revoked_at is null); $function$;
revoke all on function private.user_has_adult_work_attestation(uuid) from public,anon,authenticated;
create or replace function private.user_has_guardian_or_adult_clearance(p_user_id uuid) returns boolean language sql stable security definer set search_path to '' as $function$ select coalesce((select case when p.education_stage_key not like 'school_%' then true when p.learner_safety_status='guardian_verified' then true when private.user_has_adult_work_attestation(p_user_id) then true else false end from public.profiles p where p.id=p_user_id),false); $function$;
revoke all on function private.user_has_guardian_or_adult_clearance(uuid) from public,anon,authenticated;

create or replace function private.enforce_application_audience_access() returns trigger language plpgsql security definer set search_path to '' as $function$ declare v_stage text;v_role public.user_role;v_type public.opportunity_type;v_mode text;begin select role,education_stage_key into v_role,v_stage from public.profiles where id=new.applicant_id;if v_role<>'student' then raise exception 'student profile required';end if;if v_stage is null then raise exception 'complete your education stage before applying';end if;select opportunity_type into v_type from public.opportunities where id=new.opportunity_id;select access_mode into v_mode from public.audience_opportunity_rules where stage_key=v_stage and opportunity_type=v_type;v_mode:=coalesce(v_mode,'hidden');if v_mode in ('hidden','view_only') then raise exception 'this opportunity type is not available for your education stage';end if;if v_mode='adult_gate' and not private.user_has_adult_work_attestation(new.applicant_id) then raise exception '18+ work eligibility acknowledgement is required for this opportunity';end if;return new;end;$function$;
revoke all on function private.enforce_application_audience_access() from public,anon,authenticated;
drop trigger if exists trg_enforce_application_audience_access on public.applications;create trigger trg_enforce_application_audience_access before insert on public.applications for each row execute function private.enforce_application_audience_access();

